mapper.select:
SELECT s.id, s.name, s.category_id, s.price, s.image, s.description, s.status, s.update_time, c.name AS category_name FROM setmeal s LEFT JOIN category c ON s.category_id = c.id
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.category_id = #{categoryId}
AND s.status = #{status}
ORDER BY s.update_time DESC
